-- Dosya      : migrations/mysql/012_php_runtime.sql
-- Açıklama   : PHP kimlik/oturum, değişmez hukuk ve operasyon kayıtları; işletme fixture'ı eklemez.
ALTER TABLE `user` ADD COLUMN password_hash VARCHAR(255),ADD COLUMN php_totp_secret TEXT,ADD COLUMN php_recovery_hashes JSON,ADD COLUMN php_session_version INT NOT NULL DEFAULT 0;
CREATE TABLE php_sessions(sess_id VARBINARY(128) PRIMARY KEY,sess_data MEDIUMBLOB NOT NULL,sess_lifetime INT UNSIGNED NOT NULL,sess_time INT UNSIGNED NOT NULL,INDEX session_expiry(sess_time)) ENGINE=InnoDB;
CREATE TABLE php_login_limits(id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,attempts INT NOT NULL,expires_at DATETIME(3) NOT NULL,CHECK(attempts>=0)) ENGINE=InnoDB;
CREATE TABLE php_commands(idempotency_key VARCHAR(191) COLLATE utf8mb4_0900_bin PRIMARY KEY,request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,actor_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,result JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE audit_log(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),actor_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,action VARCHAR(100) NOT NULL,resource VARCHAR(100) NOT NULL,resource_id VARCHAR(191),details JSON NOT NULL DEFAULT(JSON_OBJECT()),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX audit_created(created_at)) ENGINE=InnoDB;
CREATE TABLE legal_documents(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),kind VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,locale VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,version INT NOT NULL,title TEXT NOT NULL,body MEDIUMTEXT NOT NULL,body_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'draft',fixture BOOLEAN NOT NULL DEFAULT false,seller_snapshot JSON NOT NULL DEFAULT(JSON_OBJECT()),approved_by VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,effective_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(kind,locale,version),CHECK(version>0),CHECK(status IN('draft','approved','effective','archived')),CHECK(fixture IN(0,1))) ENGINE=InnoDB;
CREATE TABLE order_agreements(order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,document_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,kind VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,version INT NOT NULL,locale VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,title TEXT NOT NULL,body MEDIUMTEXT NOT NULL,body_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,accepted_at DATETIME(3) NOT NULL,PRIMARY KEY(order_id,kind),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(document_id) REFERENCES legal_documents(id)) ENGINE=InnoDB;
CREATE TABLE customer_addresses(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),user_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,label VARCHAR(100) NOT NULL,fields JSON NOT NULL,country CHAR(2) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,profile_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES `user`(id),FOREIGN KEY(profile_id) REFERENCES country_address_profiles(id)) ENGINE=InnoDB;
CREATE TABLE favorites(user_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,product_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES `user`(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
DELIMITER $$
CREATE TRIGGER order_agreement_immutable BEFORE UPDATE ON order_agreements FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Order agreement is immutable'; END$$
CREATE TRIGGER effective_legal_immutable BEFORE UPDATE ON legal_documents FOR EACH ROW BEGIN
 IF OLD.status IN('effective','archived') AND(NOT(BINARY OLD.body<=>BINARY NEW.body) OR NOT(OLD.body_hash<=>NEW.body_hash) OR NOT(BINARY OLD.title<=>BINARY NEW.title) OR NOT(OLD.kind<=>NEW.kind) OR NOT(OLD.version<=>NEW.version) OR NOT(OLD.locale<=>NEW.locale) OR NOT(OLD.fixture<=>NEW.fixture) OR NOT(OLD.seller_snapshot<=>NEW.seller_snapshot) OR NOT(OLD.effective_at<=>NEW.effective_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Effective legal content is immutable'; END IF;
END$$
DELIMITER ;
